 9    TextField,
10  } from '@mui/material';
11  
12  const CONFIRM_WORD = 'DELETE';
13  
14  export function AccountDialog({ onDelete }: { onDelete?: () => void }) {
15    const [open, setOpen] = useState(false);
16    const [confirmation, setConfirmation] = useState('');
17  
18    const handleClose = () => {
19      setOpen(false);
20      setConfirmation('');
21    };
22  
23    const handleDelete = () => {
24      onDelete?.();
25      handleClose();
26    };
27  
28    return (
29      <>
30        <Button color="secondary" variant="outlined" onClick={() => setOpen(true)}>
31          Delete account
32        </Button>
33        {/* A half-typed confirmation must not be lost to a stray click outside. */}
34        <Dialog open={open} onClose={handleClose} aria-labelledby="delete-title">
35          <DialogTitle id="delete-title">Delete your account?</DialogTitle>
36          <DialogContent>
37            <DialogContentText>
38              This removes your profile and all your data. Type {CONFIRM_WORD} to confirm.
39            </DialogContentText>
40            <TextField
41              autoFocus
42              fullWidth
43              variant="outlined"
44              id="delete-confirmation"
45              label="Confirmation"
46              value={confirmation}
47              onChange={(e) => setConfirmation(e.target.value)}
48            />
49          </DialogContent>
50          <DialogActions>
51            <Button onClick={handleClose}>Cancel</Button>
52            <Button
53              color="secondary"
54              variant="contained"
55              disabled={confirmation !== CONFIRM_WORD}
56              onClick={handleDelete}
57            >
58              Delete
59            </Button>
60          </DialogActions>
61        </Dialog>
62      </>
63    );
64  }
